        for b, dl in zip(SPEC.get('bands') or [], dls):
            if d == dl:
                tags.append('DEADLINE ' + str(b.get('name')))
            elif d > dl:
                tags.append('after ' + str(b.get('name')) + ' deadline')
        L.append('  ' + fmt(d) + ': ' + s + (' [' + '; '.join(tags) + ']' if tags else ''))
        d = d + one
    return t, '\n'.join(L)

